public partial class MigrationScene {
 string inventoryFilter="ALL",inventorySearch="",inventorySelected="";int inventorySort;
 sealed class PackEntry{public string Key,Name,Kind,Description;public int Index,Tier=1,Count=1,Armor,Vitality;}
 List<PackEntry> PackItems(){var result=new List<PackEntry>();foreach(var spare in game.Craft.SpareParts.Where(p=>p.Value>0)){var part=WeaponPart.All[spare.Key];result.Add(new(){Key="weapon-mod/"+spare.Key,Kind="weapon-mod",Index=spare.Key,Tier=part.Tier,Name=part.Name,Count=spare.Value,Description=part.Slot+" / "+part.Description+"\nFit to a compatible weapon through the weapon workshop."});}foreach(int id in game.Craft.Weapons)result.Add(new(){Key="gun/"+id,Kind="weapon",Index=id,Tier=ExpeditionGame.GunTier(id),Name=(game.Life.WeaponQuality[id]>=50?"Legendary ":"")+ExpeditionGame.GunNames[id],Description=$"Weapon quality +{game.Life.WeaponQuality[id]}%.\n{(ExpeditionGame.IsMelee(id)?"Uses stamina; chainsaw also requires fuel.":ExpeditionGame.IsBow(id)?"Uses crafted arrows.":"Uses "+ExpeditionGame.AmmoNames[ExpeditionGame.AmmoClassFor(id)]+". Requires character level 2 and tier 2.")}"});foreach(var a in game.Profile.Items)result.Add(new(){Key=a.Id,Kind="armor",Index=a.GearSlot=="head"?11:a.GearSlot=="hands"?12:a.GearSlot=="feet"?13:0,Name=a.Name,Tier=a.Level,Armor=a.Armor,Vitality=a.Vitality,Description="Slot: "+a.GearSlot.ToUpperInvariant()+" / Origin: "+a.Origin+"\nArmor reduces impact damage. It does not stop bleeding."+(string.IsNullOrEmpty(a.SoulOwner)?"":"\nSOULBOUND / "+a.SoulStats)});for(int i=0;i<7;i++)if(game.Craft.Materials[i]>0)result.Add(new(){Key="material/"+i,Kind="material",Index=i,Name=ExpeditionGame.ResourceNames[i],Tier=i<3?1:i-1,Count=game.Craft.Materials[i],Description="Crafting resource. Workshop recipes show the materials they need."});
  for(int type=0;type<5;type++)if(game.Craft.Stock(type)>0)result.Add(new(){Key="ammo/"+type,Kind="ammo",Index=type,Name=ExpeditionGame.AmmoNames[type],Count=game.Craft.Stock(type),Tier=type==4?5:type>=2?3:2,Description="Class-specific ammunition. Switching weapons preserves loaded magazines and cannot convert ammunition."});
  foreach(var p in new[]{("legendary","Legendary hearts",game.Life.LegendaryCores,"Defeat the Broodheart. Ascend a maximum-tier weapon at workshop 5."),("millcore","Foreman cores",game.Life.MillCores,"Recovered from the lumber mill Foreman. Used for weapon tempering at workshop 2."),("medicine","Medical kits",game.Life.Medicine,"Supports slow health recovery for five minutes; does not patch bleeding or shorten wound healing."),("fuel","Chainsaw fuel",game.Craft.Fuel,"One unit per chainsaw burst. Crafted from resin and salvage."),("arrow","Arrows",game.Craft.Arrows,"Ammunition for the woodland bow."),("bandage","Bandages",game.Life.Bandages,"Patch one open wound. Does not restore health."),("food","Trail provisions",game.Life.Food,"Restore 40 hunger."),("water","Drinking water",game.Craft.Water,"Restore 45 hydration."),("bag","Sleeping bag kits",game.Life.Bags,"Place a respawn point through camp management."),("catalyst","Night catalysts",game.Life.NightEssence,"Recovered from night infected. Used for weapon tuning.")})if(p.Item3>0)result.Add(new(){Key=p.Item1,Kind=p.Item1,Name=p.Item2,Count=p.Item3,Tier=p.Item1=="bag"?2:p.Item1=="catalyst"?3:1,Description=p.Item4});if(game.Life.RawWater>0)result.Add(new(){Key="raw-water",Kind="raw-water",Name="Untreated water / illness risk",Count=game.Life.RawWater,Tier=1,Description="35% illness risk. Y opens boiling and filters. Bottled and purified water are safe."});return result;
 }
 static string PackGlyph(PackEntry item)=>item.Kind=="material"?new[]{"timber","stone","fiber","resin","alloy","electronics","bio"}[item.Index]:item.Kind;
 Label PackLabel(VBoxContainer box,string text,int size=13){var l=new Label{Text=text,AutowrapMode=TextServer.AutowrapMode.WordSmart};l.AddThemeFontSizeOverride("font_size",size);box.AddChild(l);return l;}
 void SurvivorInventory(){var b=Panel("SURVIVOR / INVENTORY");coopMenu="equipment";menu.Position=new(40,65);menu.Size=new(1200,565);b.AddThemeConstantOverride("separation",6);var row=new HBoxContainer();row.AddThemeConstantOverride("separation",16);b.AddChild(row);
  var profile=new VBoxContainer{CustomMinimumSize=new(250,0)};row.AddChild(profile);PackLabel(profile,"EQUIPPED / FIELD LOADOUT",12);Portrait(profile);var armor=game.Profile.Items.FirstOrDefault(a=>a.Id==game.Profile.Equipped);var weaponSlot=new Button{Text="PRIMARY WEAPON\n"+ExpeditionGame.GunNames[game.Craft.Weapon],CustomMinimumSize=new(250,40)};profile.AddChild(weaponSlot);var armorSlot=new Button{Text="CHEST ARMOR\n"+(armor==null?"UNARMORED":"T"+armor.Level+" / ARMOR "+armor.Armor),CustomMinimumSize=new(250,40)};profile.AddChild(armorSlot);GearSlots(profile);Button(profile,"WEAPON PARTS / WORKSHOP",ShowWeaponParts);Button(profile,"SOULBOUND ARMORY",ShowSoulArmory);PackLabel(profile,$"MAX HEALTH {(int)game.MaxHealth}\nWORKSHOP {game.Craft.BenchTier}  /  DISCOVERED T{game.Craft.UnlockedTier}\n{ExpeditionGame.AmmoNames[game.Craft.AmmoClass]}\n{game.Craft.Ammo} LOADED / {game.Craft.Reserve} RESERVE",12);
  var center=new VBoxContainer{CustomMinimumSize=new(580,0)};row.AddChild(center);var filters=new HBoxContainer();center.AddChild(filters);foreach(string category in new[]{"ALL","WEAPONS","ARMOR","MATERIALS","SUPPLIES"}){string copy=category;var button=new Button{Text=category,ToggleMode=true,ButtonPressed=inventoryFilter==category};button.AddThemeFontSizeOverride("font_size",11);filters.AddChild(button);button.Pressed+=()=>{inventoryFilter=copy;SurvivorInventory();};}
  var toolbar=new HBoxContainer();center.AddChild(toolbar);var search=new LineEdit{PlaceholderText="Search your pack...",Text=inventorySearch,CustomMinimumSize=new(390,34)};toolbar.AddChild(search);var sort=new OptionButton{CustomMinimumSize=new(180,34)};sort.AddItem("SORT / TYPE");sort.AddItem("SORT / TIER");sort.AddItem("SORT / NAME");sort.Select(inventorySort);toolbar.AddChild(sort);
  var scroll=new ScrollContainer{CustomMinimumSize=new(580,310)};center.AddChild(scroll);var grid=new GridContainer{Columns=4,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};grid.AddThemeConstantOverride("h_separation",7);grid.AddThemeConstantOverride("v_separation",7);scroll.AddChild(grid);var details=new VBoxContainer{CustomMinimumSize=new(265,0)};row.AddChild(details);var all=PackItems();
  void Detail(PackEntry item){ClearChildren(details);if(item==null){PackLabel(details,"NO ITEMS FOUND",20);PackLabel(details,"Try a different category or search.");return;}inventorySelected=item.Key;ItemPreview(details,item.Kind,item.Index,item.Tier,item.Kind=="armor"?item.Key:"");PackLabel(details,item.Name.ToUpperInvariant(),20);PackLabel(details,$"TIER {item.Tier} / {item.Kind.ToUpperInvariant()} / x{item.Count}",12);details.AddChild(new HSeparator());PackLabel(details,item.Description,13);if(item.Kind=="armor"){PackLabel(details,$"ARMOR {item.Armor}\nMAX HEALTH +{item.Vitality}",16);}if(item.Kind=="weapon")PackLabel(details,$"DAMAGE BONUS +{game.Life.WeaponQuality[item.Index]}%",15);details.AddChild(new Control{SizeFlagsVertical=Control.SizeFlags.ExpandFill});bool equipped=item.Kind=="weapon"?item.Index==game.Craft.Weapon:item.Kind=="armor"&&game.IsGearEquipped(item.Key);bool usable=item.Kind=="bandage"?game.Life.Wounds.Any(w=>!w.Patched):item.Kind=="food"?game.Life.Hunger<100:item.Kind=="water"?game.Life.Hydration<100:true;
   string title=item.Kind=="weapon-mod"?"OPEN WEAPON WORKSHOP":equipped?"EQUIPPED":item.Kind is "weapon" or "armor"?"EQUIP":item.Kind is "arrow" or "fuel"?"OPEN WORKSHOP":item.Kind=="bag"?"MANAGE CAMPS":item.Kind is "material" or "catalyst" or "millcore"?"OPEN WORKSHOP":item.Kind=="bandage"?"PATCH WOUND":"USE ITEM";var action=new Button{Text=title,Disabled=equipped||!usable,CustomMinimumSize=new(260,40)};details.AddChild(action);if(!usable)PackLabel(details,item.Kind=="bandage"?"No open wound to patch.":"This need is already full.",12);action.Pressed+=()=>{if(item.Kind=="weapon-mod")ShowWeaponParts();else if(item.Kind=="weapon"){axeEquipped=false;if(!CoopRequest("equip",item.Index.ToString()))game.Change(()=>game.Equip(item.Index));reloadClock=0;BuildGun();SurvivorInventory();}else if(item.Kind=="armor"){if(!CoopRequest("armor",item.Key))game.Change(()=>game.EquipGear(item.Key));SurvivorInventory();}else if(item.Kind=="bag")ShowCamps();else if(item.Kind is "material" or "catalyst" or "millcore" or "arrow" or "fuel" or "ammo" or "legendary")ShowCrafting();else UsePackItem(item.Kind);};
  }
  void Rebuild(){ClearChildren(grid);IEnumerable<PackEntry> entries=all.Where(p=>(inventoryFilter=="ALL"||inventoryFilter=="WEAPONS"&&p.Kind is ("weapon" or "weapon-mod")||inventoryFilter=="ARMOR"&&p.Kind=="armor"||inventoryFilter=="MATERIALS"&&p.Kind=="material"||inventoryFilter=="SUPPLIES"&&p.Kind is not ("weapon" or "armor" or "material"))&&p.Name.Contains(inventorySearch,StringComparison.OrdinalIgnoreCase));entries=inventorySort==1?entries.OrderByDescending(p=>p.Tier).ThenBy(p=>p.Name):inventorySort==2?entries.OrderBy(p=>p.Name):entries.OrderBy(p=>p.Kind=="weapon"?0:p.Kind=="armor"?1:p.Kind=="material"?3:2).ThenBy(p=>p.Tier).ThenBy(p=>p.Name);var visible=entries.ToList();if(!visible.Any(p=>p.Key==inventorySelected))inventorySelected=visible.FirstOrDefault()?.Key??"";foreach(var item in visible){var copy=item;bool selected=inventorySelected==item.Key;bool equipped=item.Kind=="weapon"?item.Index==game.Craft.Weapon:item.Kind=="armor"&&game.IsGearEquipped(item.Key);var card=new Button{CustomMinimumSize=new(135,110),TooltipText=item.Name+"\n"+item.Description};card.AddThemeStyleboxOverride("normal",Style(selected?new Color(.20f,.26f,.23f):new Color(.075f,.11f,.11f),selected?new Color(.77f,.65f,.39f):equipped?new Color(.47f,.65f,.42f):new Color(.27f,.34f,.29f),selected?2:1,5));grid.AddChild(card);card.AddChild(new InventoryGlyph{Kind=PackGlyph(item),Position=new(9,8),Size=new(33,33),MouseFilter=Control.MouseFilterEnum.Ignore});var badge=new Label{Text="T"+item.Tier+(equipped?" / EQ":""),Position=new(62,10),MouseFilter=Control.MouseFilterEnum.Ignore};badge.AddThemeFontSizeOverride("font_size",11);card.AddChild(badge);var name=new Label{Text=item.Name,Position=new(8,46),Size=new(119,42),AutowrapMode=TextServer.AutowrapMode.WordSmart,MaxLinesVisible=3,MouseFilter=Control.MouseFilterEnum.Ignore};name.AddThemeFontSizeOverride("font_size",11);card.AddChild(name);var count=new Label{Text="x"+item.Count,Position=new(98,87),MouseFilter=Control.MouseFilterEnum.Ignore};count.AddThemeFontSizeOverride("font_size",11);card.AddChild(count);card.Pressed+=()=>{inventorySelected=copy.Key;Rebuild();};}Detail(visible.FirstOrDefault(p=>p.Key==inventorySelected));}
  search.TextChanged+=s=>{inventorySearch=s;Rebuild();};sort.ItemSelected+=i=>{inventorySort=(int)i;Rebuild();};weaponSlot.Pressed+=()=>{inventoryFilter="WEAPONS";inventorySearch="";inventorySelected="gun/"+game.Craft.Weapon;SurvivorInventory();};armorSlot.Pressed+=()=>{inventoryFilter="ARMOR";inventorySearch="";inventorySelected=game.Profile.Equipped??"";SurvivorInventory();};Rebuild();inventoryLiveStatus=PackLabel(b,$"HEALTH {(int)game.Life.Health}/{(int)game.MaxHealth}   /   FOOD {(int)game.Life.Hunger}   WATER {(int)game.Life.Hydration}   ENERGY {(int)game.Life.Energy}\n{WoundStatus()}",12);Button(b,"BACK TO WORLD",CloseMenu);
 }
 void UsePackItem(string kind){string op=kind=="raw-water"?"rawdrink":kind=="medicine"?"medicine":kind=="bandage"?"bandage":kind=="food"?"eat":"drink";if(CoopRequest(op))return;game.Change(()=>{if(kind=="raw-water")game.Drink(true);else if(kind=="medicine"&&game.Life.Medicine>0){game.Life.Medicine--;game.Life.Sickness=0;game.Life.RecoveryBoost=300;game.Notice="Medical support / five minutes of improved slow recovery";}else if(kind=="bandage")game.Notice=game.Life.Patch()?"Wound patched / recovery takes time":"No open wound";else if(kind=="food"&&game.Life.Food>0){game.Life.Food--;game.Life.Hunger=Math.Min(100,game.Life.Hunger+40);game.Notice="Ate provisions";}else if(kind=="water"&&game.Craft.Water>0){game.Drink();}});SurvivorInventory();}
 async void CaptureInventoryHud(){try{testing=true;CloseMenu();ClearEnemies();game.World.Changes.Time=1050;Teleport(game.World.RouteX(-500),-500);camera.Position=new(0,1.65f,0);camera.LookAt(Ground(game.World.RouteX(-540),-540)+Vector3.Up*1.65f);game.Life.Hunger=72;game.Life.Hydration=61;game.Life.Energy=84;game.Stamina=68;game.Life.Health=83;for(int i=0;i<7;i++)game.Craft.Materials[i]=12+i*3;game.Craft.Weapons=new(){0,1,2,3};game.Craft.BenchTier=game.Craft.UnlockedTier=3;game.Life.Bags=2;game.Life.NightEssence=4;game.Profile.Items.Add(new ExpeditionRelic{Id="preview/plate",Name="Chest plate of the Old Guard",Origin="The Old Guard",Level=2,Armor=23,Vitality=6});game.Profile.Equipped="preview/plate";await ArtShot("inventory-01-hud");game.Life.Wounds.Add(new ExpeditionWound{Blood=260});await ArtShot("inventory-02-bleeding");inventorySelected="preview/plate";inventoryFilter="ALL";SurvivorInventory();await ArtShot("inventory-03-pack");inventoryFilter="SUPPLIES";inventorySelected="bandage";SurvivorInventory();await ArtShot("inventory-04-supplies");GD.Print("PASS / HUD and inventory GPU captures");GetTree().Quit();}catch(Exception ex){GD.PushError(ex.ToString());GetTree().Quit(1);}}
